Your expense tracker is below: add what you spend, see the month's total, and watch it against a budget. Entries stay only while this page is open, so don't close it before you've noted what you need.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Monthly expenses</title>
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:110px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:#c0392b;padding:4px 8px}
.big{font-size:26px;font-weight:600}
.bar{height:8px;background:#e5e8e5;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar>div{height:100%;background:#2f7d5b}
.over{background:#c0392b!important}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#777;font-size:13px}
</style></head><body>
<h2>Monthly expenses</h2>

<div class="card">
<div class="row">
<input id="month" type="month">
<input id="budget" type="number" placeholder="Budget (₹)" value="50000">
</div>
<div class="muted">Spent this month</div>
<div class="big" id="total">₹0</div>
<div class="bar"><div id="tb" style="width:0"></div></div>
<div class="muted" id="left"></div>
</div>

<div class="card">
<div class="row">
<input id="desc" placeholder="What for?">
<input id="amt" type="number" placeholder="Amount (₹)">
</div>
<div class="row">
<select id="cat">
<option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
</select>
<input id="day" type="date">
<button id="add">Add</button>
</div>
</div>

<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>

<script>
var items=[];
try{items=JSON.parse(localStorage.getItem("foo_exp")||"[]")}catch(e){}
var $=function(i){return document.getElementById(i)};
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
var today=new Date().toISOString().slice(0,10);
$("day").value=today;$("month").value=today.slice(0,7);
function save(){try{localStorage.setItem("foo_exp",JSON.stringify(items))}catch(e){}}
function render(){
  var m=$("month").value,b=+$("budget").value||0;
  var cur=items.filter(function(x){return x.d.slice(0,7)===m});
  var tot=cur.reduce(function(s,x){return s+x.a},0);
  $("total").textContent=fmt(tot);
  var pct=b?Math.min(100,tot/b*100):0;
  $("tb").style.width=pct+"%";
  $("tb").className=b&&tot>b?"over":"";
  $("left").textContent=b?(tot>b?"Over budget by "+fmt(tot-b):fmt(b-tot)+" left of "+fmt(b)):"";
  var by={};cur.forEach(function(x){by[x.c]=(by[x.c]||0)+x.a});
  var c=$("cats");c.innerHTML="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    var w=document.createElement("div");
    var t=document.createElement("div");t.className="item";t.style.border="0";
    t.innerHTML="<span></span><span></span>";
    t.children[0].textContent=k;t.children[1].textContent=fmt(by[k]);
    var bar=document.createElement("div");bar.className="bar";
    var f=document.createElement("div");f.style.width=(by[k]/tot*100)+"%";bar.appendChild(f);
    w.appendChild(t);w.appendChild(bar);c.appendChild(w);
  });
  if(!cur.length)c.innerHTML='<div class="muted">Nothing yet.</div>';
  var l=$("list");l.innerHTML="";
  cur.slice().sort(function(a,b){return a.d<b.d?1:-1}).forEach(function(x){
    var r=document.createElement("div");r.className="item";
    var s=document.createElement("span");
    s.textContent=x.t+" ("+x.c+") ";
    var dt=document.createElement("span");dt.className="muted";dt.textContent=x.d;
    s.appendChild(dt);
    var e=document.createElement("span");
    e.textContent=fmt(x.a)+" ";
    var del=document.createElement("button");del.className="x";del.textContent="✕";
    del.onclick=function(){items=items.filter(function(y){return y!==x});save();render()};
    e.appendChild(del);
    r.appendChild(s);r.appendChild(e);l.appendChild(r);
  });
}
$("add").onclick=function(){
  var a=+$("amt").value;
  if(!a||a<=0)return;
  items.push({t:$("desc").value.trim()||"Expense",a:a,c:$("cat").value,d:$("day").value||today});
  $("desc").value="";$("amt").value="";
  save();render();
};
$("month").onchange=render;$("budget").oninput=render;
render();
</script>
</body></html>
```

